const context = options.contextData;
	const viewmodel = options.contextData.viewmodel;
	const selectedElement = context.selectedElement;
	const resultSettings = {
		hidden: true
	};
	if (selectedElement) {
		const modelCursor = viewmodel.Cursor();
		const ancesstorElement = modelCursor.commonAncestor;
		if(selectedElement.is('ArasTextXmlSchemaElement') && selectedElement === ancesstorElement && selectedElement.GetSelectedLinksCount()) {
			resultSettings.hidden = false;
		}
	}

	return resultSettings;
